#include <vector>

class Solution {
public:
    long long countSubmatrices(std::vector<std::vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<int>> rows(m, std::vector<int>(n, 0));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] <= k) {
                    if (j > 0 && grid[i][j] <= grid[i][j - 1]) {
                        rows[i][j] = rows[i][j - 1] + 1;
                    } else {
                        rows[i][j] = 1;
                    }
                }
            }
        }

        long long ans = 0;
        for (int j = 0; j < n; ++j) {
            std::vector<std::pair<int, int>> stack;
            long long curr_sum = 0;
            for (int i = 0; i < m; ++i) {
                int length = rows[i][j];
                int cnt = 1;
                while (!stack.empty() && stack.back().first >= length) {
                    auto prev = stack.back();
                    stack.pop_back();
                    curr_sum -= (long long)prev.first * prev.second;
                    cnt += prev.second;
                }
                stack.push_back({length, cnt});
                curr_sum += (long long)length * cnt;
                ans += curr_sum;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long countSubmatrices(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        int[][] rows = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] <= k) {
                    if (j > 0 && grid[i][j] <= grid[i][j - 1]) {
                        rows[i][j] = rows[i][j - 1] + 1;
                    } else {
                        rows[i][j] = 1;
                    }
                }
            }
        }

        long ans = 0;
        for (int j = 0; j < n; j++) {
            List<int[]> stack = new ArrayList<>();
            long currSum = 0;
            for (int i = 0; i < m; i++) {
                int length = rows[i][j];
                int cnt = 1;
                while (!stack.isEmpty() && stack.get(stack.size() - 1)[0] >= length) {
                    int[] prev = stack.remove(stack.size() - 1);
                    currSum -= (long) prev[0] * prev[1];
                    cnt += prev[1];
                }
                stack.add(new int[]{length, cnt});
                currSum += (long) length * cnt;
                ans += currSum;
            }
        }
        return ans;
    }
}

var countSubmatrices = function(grid, k) {
    const m = grid.length, n = grid[0].length;
    const rows = Array.from({ length: m }, () => new Int32Array(n));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] <= k) {
                if (j > 0 && grid[i][j] <= grid[i][j - 1]) {
                    rows[i][j] = rows[i][j - 1] + 1;
                } else {
                    rows[i][j] = 1;
                }
            }
        }
    }

    let ans = 0;
    for (let j = 0; j < n; j++) {
        const stack = [];
        let currSum = 0;
        for (let i = 0; i < m; i++) {
            const length = rows[i][j];
            let cnt = 1;
            while (stack.length > 0 && stack[stack.length - 1][0] >= length) {
                const [prevL, prevCnt] = stack.pop();
                currSum -= prevL * prevCnt;
                cnt += prevCnt;
            }
            stack.push([length, cnt]);
            currSum += length * cnt;
            ans += currSum;
        }
    }
    return ans;
};
